-- Desktop-only Hyprland settings
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.monitor({
    output = "DP-2",
    mode = "3840x2160@120.00Hz",
    position = "0x0",
    scale = "1",
})

hl.monitor({
    output = "DP-3",
    mode = "2560x1440@120.00Hz",
    position = "3840x0",
    scale = "1",
})

hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")
hl.env("LIBVA_DRIVER_NAME", "nvidia")
hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")
hl.config({
    general = {
        gaps_out = 5,
    },
})



-- Pin workspace 1 to the left monitor and 2 to the right
hl.workspace_rule({ workspace = "1", monitor = "DP-2", default = true })
hl.workspace_rule({ workspace = "2", monitor = "DP-3", default = true })
